    '        <polyline points="22 4 12 14.01 9 11.01" />\n'
    "      </svg>\n"
    "    );\n"
    "  }\n"
    '  if (variant === "warning") {\n'
    "    return (\n"
    "      <svg\n"
    '        aria-hidden="true"\n'
    '        width="18"\n'
    '        height="18"\n'
    '        viewBox="0 0 24 24"\n'
    '        fill="none"\n'
    "        stroke={color}\n"
    '        strokeWidth="2"\n'
    '        strokeLinecap="round"\n'
    '        strokeLinejoin="round"\n'
    "      >\n"
    '        <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />\n'
    '        <line x1="12" y1="9" x2="12" y2="13" />\n'
    '        <line x1="12" y1="17" x2="12.01" y2="17" />\n'
    "      </svg>\n"
    "    );\n"
    "  }\n"
    '  if (variant === "error") {\n'
    "    return (\n"
    "      <svg\n"
    '        aria-hidden="true"\n'
    '        width="18"\n'
    '        height="18"\n'
    '        viewBox="0 0 24 24"\n'
    '        fill="none"\n'
    "        stroke={color}\n"
    '        strokeWidth="2"\n'
    '        strokeLinecap="round"\n'
    '        strokeLinejoin="round"\n'
    "      >\n"
    '        <circle cx="12" cy="12" r="10" />\n'
