_DRAWER_COMPONENT = (
    '"use client";\n\n'
    'import React, { useEffect, useId } from "react";\n\n'
    'export type DrawerPosition = "left" | "right" | "top" | "bottom";\n'
    'export type DrawerSize = "sm" | "md" | "lg" | "xl" | "full";\n\n'
    "export interface DrawerProps {\n"
    "  open: boolean;\n"
    "  onClose: () => void;\n"
    "  position?: DrawerPosition;\n"
    "  size?: DrawerSize;\n"
    "  children?: React.ReactNode;\n"
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "  closeOnBackdropClick?: boolean;\n"
    "  closeOnEscape?: boolean;\n"
    "  showCloseButton?: boolean;\n"
    "  ariaLabel?: string;\n"
    "}\n\n"
    "export interface DrawerHeaderProps {\n"
    "  children: React.ReactNode;\n"
    "  onClose?: () => void;\n"
    "  showCloseButton?: boolean;\n"
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "}\n\n"
    "export interface DrawerTitleProps {\n"
    "  children: React.ReactNode;\n"
    '  as?: "h1" | "h2" | "h3" | "h4" | "div";\n'
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "}\n\n"
    "export interface DrawerDescriptionProps {\n"
    "  children: React.ReactNode;\n"
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "}\n\n"
    "export interface DrawerContentProps {\n"
    "  children: React.ReactNode;\n"
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "}\n\n"
    "export interface DrawerFooterProps {\n"
    "  children: React.ReactNode;\n"
    '  align?: "left" | "right" | "between" | "center";\n'
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "}\n\n"
    "const sizeMap: Record<DrawerSize, string> = {\n"
    '  sm: "320px",\n'
    '  md: "400px",\n'
    '  lg: "540px",\n'
    '  xl: "720px",\n'
    '  full: "100%",\n'
    "};\n\n"
    "const verticalSizeMap: Record<DrawerSize, string> = {\n"
    '  sm: "30vh",\n'
    '  md: "45vh",\n'
    '  lg: "60vh",\n'
    '  xl: "80vh",\n'
    '  full: "100vh",\n'
    "};\n\n"
    "export function Drawer({\n"
    "  open,\n"
    "  onClose,\n"
    '  position = "right",\n'
    '  size = "md",\n'
    "  children,\n"
    "  className,\n"
    "  style,\n"
    "  closeOnBackdropClick = true,\n"
    "  closeOnEscape = true,\n"
    "  showCloseButton = true,\n"
    "  ariaLabel,\n"
    "}: DrawerProps) {\n"
    "  const instanceId = useId();\n"
    "  const titleId = `drawer-title-${instanceId}`;\n"
    "  const descId = `drawer-desc-${instanceId}`;\n\n"
    "  useEffect(() => {\n"
    "    if (!open) return;\n"
    "    const handleKeyDown = (e: KeyboardEvent) => {\n"
    '      if (closeOnEscape && e.key === "Escape") {\n'
    "        onClose();\n"
    "      }\n"
    "    };\n"
    '    window.addEventListener("keydown", handleKeyDown);\n'
    '    return () => window.removeEventListener("keydown", handleKeyDown);\n'
    "  }, [open, closeOnEscape, onClose]);\n\n"
    "  useEffect(() => {\n"
    "    if (!open) return;\n"
    "    const originalOverflow = document.body.style.overflow;\n"
    '    document.body.style.overflow = "hidden";\n'
    "    return () => {\n"
    "      document.body.style.overflow = originalOverflow;\n"
    "    };\n"
    "  }, [open]);\n\n"
    "  if (!open) {\n"
    "    return null;\n"
    "  }\n\n"
    "  const handleBackdropClick = (e: React.MouseEvent) => {\n"
    "    if (e.target === e.currentTarget && closeOnBackdropClick) {\n"
    "      onClose();\n"
    "    }\n"
    "  };\n\n"
    '  const isHorizontal = position === "left" || position === "right";\n'
    "  const dimensionStyle: React.CSSProperties = isHorizontal\n"
    "    ? {\n"
    "        width: sizeMap[size],\n"
    '        maxWidth: "100vw",\n'
    '        height: "100vh",\n'
    "        top: 0,\n"
    "        bottom: 0,\n"
    '        left: position === "left" ? 0 : undefined,\n'
    '        right: position === "right" ? 0 : undefined,\n'
    "      }\n"
    "    : {\n"
    "        height: verticalSizeMap[size],\n"
    '        maxHeight: "100vh",\n'
    '        width: "100vw",\n'
    "        left: 0,\n"
    "        right: 0,\n"
    '        top: position === "top" ? 0 : undefined,\n'
    '        bottom: position === "bottom" ? 0 : undefined,\n'
    "      };\n\n"
    "  return (\n"
    "    <div\n"
    '      role="dialog"\n'
    '      aria-modal="true"\n'
    "      aria-labelledby={titleId}\n"
    "      aria-describedby={descId}\n"
    "      aria-label={ariaLabel}\n"
    "      onClick={handleBackdropClick}\n"
    "      style={{\n"
    '        position: "fixed",\n'
    "        inset: 0,\n"
    "        zIndex: 50,\n"
    '        backgroundColor: "rgba(15, 23, 42, 0.5)",\n'
    '        backdropFilter: "blur(2px)",\n'
    '        display: "flex",\n'
    "      }}\n"
    "    >\n"
    "      <div\n"
    "        className={className}\n"
    "        style={{\n"
    '          position: "fixed",\n'
    '          backgroundColor: "#ffffff",\n'
    '          display: "flex",\n'
    '          flexDirection: "column",\n'
    "          boxShadow:\n"
    '            position === "right"\n'
    '              ? "-4px 0 24px rgba(0, 0, 0, 0.15)"\n'
    '              : position === "left"\n'
    '              ? "4px 0 24px rgba(0, 0, 0, 0.15)"\n'
    '              : position === "bottom"\n'
    '              ? "0 -4px 24px rgba(0, 0, 0, 0.15)"\n'
    '              : "0 4px 24px rgba(0, 0, 0, 0.15)",\n'
    "          zIndex: 51,\n"
    "          ...dimensionStyle,\n"
    "          ...style,\n"
    "        }}\n"
    "      >\n"
    "        {React.Children.map(children, (child) => {\n"
    "          if (!React.isValidElement(child)) return child;\n"
    "          return React.cloneElement(child as React.ReactElement<any>, {\n"
    "            onClose: (child.props as any).onClose ?? onClose,\n"
    "            showCloseButton: (child.props as any).showCloseButton ?? showCloseButton,\n"
    "            id: (child.props as any).id,\n"
    "          });\n"
    "        })}\n"
    "      </div>\n"
    "    </div>\n"
    "  );\n"
    "}\n\n"
    "export function DrawerHeader({\n"
    "  children,\n"
    "  onClose,\n"
    "  showCloseButton = true,\n"
    "  className,\n"
    "  style,\n"
    "}: DrawerHeaderProps) {\n"
    "  return (\n"
    "    <div\n"
    "      className={className}\n"
    "      style={{\n"
    '        padding: "16px 20px",\n'
    '        borderBottom: "1px solid #e2e8f0",\n'
    '        display: "flex",\n'
    '        alignItems: "flex-start",\n'
    '        justifyContent: "space-between",\n'
    "        gap: 12,\n"
    "        ...style,\n"
    "      }}\n"
    "    >\n"
    '      <div style={{ flex: 1, minWidth: 0 }}>{children}</div>\n'
    "      {showCloseButton && onClose && (\n"
    "        <button\n"
    '          type="button"\n'
    "          onClick={onClose}\n"
    '          aria-label="Close drawer"\n'
    "          style={{\n"
    '            background: "transparent",\n'
    '            border: "none",\n'
    '            color: "#64748b",\n'
    '            cursor: "pointer",\n'
    "            padding: 4,\n"
    "            lineHeight: 1,\n"
    "            fontSize: 20,\n"
    "            borderRadius: 4,\n"
    "            flexShrink: 0,\n"
    "          }}\n"
    "        >\n"
    "          &times;\n"
    "        </button>\n"
    "      )}\n"
    "    </div>\n"
    "  );\n"
    "}\n\n"
    "export function DrawerTitle({\n"
    "  children,\n"
    '  as = "h2",\n'
    "  className,\n"
    "  style,\n"
    "}: DrawerTitleProps) {\n"
    "  const Component = as;\n"
    "  return (\n"
    "    <Component\n"
    "      className={className}\n"
    "      style={{\n"
    "        margin: 0,\n"
    "        fontSize: 18,\n"
    "        fontWeight: 600,\n"
    '        color: "#0f172a",\n'
    "        lineHeight: 1.4,\n"
    "        ...style,\n"
    "      }}\n"
    "    >\n"
    "      {children}\n"
    "    </Component>\n"
    "  );\n"
    "}\n\n"
    "export function DrawerDescription({\n"
    "  children,\n"
    "  className,\n"
    "  style,\n"
    "}: DrawerDescriptionProps) {\n"
    "  return (\n"
    "    <p\n"
    "      className={className}\n"
    "      style={{\n"
    '        margin: "4px 0 0 0",\n'
    "        fontSize: 14,\n"
    '        color: "#64748b",\n'
    "        lineHeight: 1.5,\n"
    "        ...style,\n"
    "      }}\n"
    "    >\n"
    "      {children}\n"
    "    </p>\n"
    "  );\n"
    "}\n\n"
    "export function DrawerContent({\n"
    "  children,\n"
    "  className,\n"
    "  style,\n"
    "}: DrawerContentProps) {\n"
    "  return (\n"
    "    <div\n"
    "      className={className}\n"
    "      style={{\n"
    "        flex: 1,\n"
    '        overflowY: "auto",\n'
    '        padding: "20px",\n'
    "        ...style,\n"
    "      }}\n"
    "    >\n"
    "      {children}\n"
    "    </div>\n"
    "  );\n"
    "}\n\n"
    "export function DrawerFooter({\n"
    "  children,\n"
    '  align = "right",\n'
    "  className,\n"
    "  style,\n"
    "}: DrawerFooterProps) {\n"
    "  const justifyMap: Record<string, string> = {\n"
    '    left: "flex-start",\n'
    '    right: "flex-end",\n'
    '    between: "space-between",\n'
    '    center: "center",\n'
    "  };\n"
    "  return (\n"
    "    <div\n"
    "      className={className}\n"
    "      style={{\n"
    '        padding: "16px 20px",\n'
    '        borderTop: "1px solid #e2e8f0",\n'
    '        display: "flex",\n'
    '        alignItems: "center",\n'
    '        justifyContent: justifyMap[align] || "flex-end",\n'
    "        gap: 12,\n"
    '        backgroundColor: "#f8fafc",\n'
    "        ...style,\n"
    "      }}\n"
    "    >\n"
    "      {children}\n"
    "    </div>\n"
    "  );\n"
    "}\n\n"
    "export default Drawer;\n"
)


def render_drawer_component() -> str:
    """Return the static TypeScript implementation of the Drawer component."""
    return _DRAWER_COMPONENT


_AVATAR_COMPONENT = (
    '"use client";\n\n'
    'import React, { useState } from "react";\n\n'
    'export type AvatarShape = "circle" | "rounded" | "square";\n'
    'export type AvatarSize = "xs" | "sm" | "md" | "lg" | "xl";\n'
    'export type AvatarStatus = "online" | "offline" | "busy" | "away";\n\n'
    "export interface AvatarProps {\n"
    "  src?: string;\n"
    "  alt?: string;\n"
    "  name?: string;\n"
    "  shape?: AvatarShape;\n"
    "  size?: AvatarSize;\n"
    "  status?: AvatarStatus;\n"
    '  statusPosition?: "top-right" | "bottom-right" | "top-left" | "bottom-left";\n'
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "}\n\n"
    "export interface AvatarGroupProps {\n"
    "  children: React.ReactNode;\n"
    "  max?: number;\n"
    "  size?: AvatarSize;\n"
    "  shape?: AvatarShape;\n"
    "  spacing?: number;\n"
    "  className?: string;\n"
    "  style?: React.CSSProperties;\n"
    "}\n\n"
    "const sizeMap: Record<AvatarSize, { dimension: number; fontSize: number; statusSize: number }> = {\n"
    "  xs: { dimension: 24, fontSize: 10, statusSize: 6 },\n"
    "  sm: { dimension: 32, fontSize: 12, statusSize: 8 },\n"
    "  md: { dimension: 40, fontSize: 14, statusSize: 10 },\n"
    "  lg: { dimension: 48, fontSize: 18, statusSize: 12 },\n"
    "  xl: { dimension: 64, fontSize: 24, statusSize: 14 },\n"
    "};\n\n"
    "const shapeBorderRadius: Record<AvatarShape, string> = {\n"
    '  circle: "50%",\n'
    '  rounded: "8px",\n'
    '  square: "0px",\n'
    "};\n\n"
    "const statusColors: Record<AvatarStatus, string> = {\n"
    '  online: "#22c55e",\n'
    '  offline: "#94a3b8",\n'
    '  busy: "#ef4444",\n'
    '  away: "#f59e0b",\n'
    "};\n\n"
    "const palette = [\n"
    '  "#2563eb",\n'
    '  "#7c3aed",\n'
    '  "#db2777",\n'
    '  "#ea580c",\n'
    '  "#16a34a",\n'
    '  "#0891b2",\n'
    '  "#4f46e5",\n'
    '  "#ca8a04",\n'
    "];\n\n"
    "function getColorFromName(name: string): string {\n"
    "  let hash = 0;\n"
    "  for (let i = 0; i < name.length; i++) {\n"
    "    hash = name.charCodeAt(i) + ((hash << 5) - hash);\n"
    "  }\n"
    "  const index = Math.abs(hash) % palette.length;\n"
    "  return palette[index];\n"
    "}\n\n"
    "function getInitials(name: string): string {\n"
    "  if (!name) return \"\";\n"
    "  const parts = name.trim().split(/\\s+/);\n"
    "  if (parts.length === 1) {\n"
    "    return parts[0].substring(0, 2).toUpperCase();\n"
    "  }\n"
    "  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();\n"
    "}\n\n"
    "export function Avatar({\n"
    "  src,\n"
    "  alt,\n"
    "  name,\n"
    '  shape = "circle",\n'
    '  size = "md",\n'
    "  status,\n"
    '  statusPosition = "bottom-right",\n'
    "  className,\n"
    "  style,\n"
    "}: AvatarProps) {\n"
    "  const [imageError, setImageError] = useState(false);\n"
    "  const cfg = sizeMap[size];\n"
    "  const borderRadius = shapeBorderRadius[shape];\n\n"
    "  const hasImage = Boolean(src && !imageError);\n"
    '  const initials = !hasImage && name ? getInitials(name) : "";\n'
    '  const bgColor = initials && name ? getColorFromName(name) : "#e2e8f0";\n'
    '  const label = alt || name || "User avatar";\n\n'
    "  const statusPositions: Record<string, React.CSSProperties> = {\n"
    "    \"top-right\": { top: 0, right: 0 },\n"
    "    \"bottom-right\": { bottom: 0, right: 0 },\n"
    "    \"top-left\": { top: 0, left: 0 },\n"
    "    \"bottom-left\": { bottom: 0, left: 0 },\n"
    "  };\n\n"
    "  return (\n"
    "    <div\n"
    '      role="img"\n'
    "      aria-label={status ? `${label} (${status})` : label}\n"
    "      className={className}\n"
    "      style={{\n"
    '        position: "relative",\n'
    '        display: "inline-flex",\n'
    '        alignItems: "center",\n'
    '        justifyContent: "center",\n'
    "        width: cfg.dimension,\n"
    "        height: cfg.dimension,\n"
    "        borderRadius,\n"
    "        backgroundColor: bgColor,\n"
    '        color: initials ? "#ffffff" : "#64748b",\n'
    "        fontWeight: 600,\n"
    "        fontSize: cfg.fontSize,\n"
    '        userSelect: "none",\n'
    "        flexShrink: 0,\n"
    '        overflow: "visible",\n'
    "        ...style,\n"
    "      }}\n"
    "    >\n"
    "      <div\n"
    "        style={{\n"
    '          width: "100%",\n'
    '          height: "100%",\n'
    "          borderRadius,\n"
    '          overflow: "hidden",\n'
    '          display: "flex",\n'
    '          alignItems: "center",\n'
    '          justifyContent: "center",\n'
    "        }}\n"
    "      >\n"
    "        {hasImage ? (\n"
    "          <img\n"
    "            src={src}\n"
    "            alt={label}\n"
    "            onError={() => setImageError(true)}\n"
    "            style={{\n"
    '              width: "100%",\n'
    '              height: "100%",\n'
    '              objectFit: "cover",\n'
    "            }}\n"
    "          />\n"
    "        ) : initials ? (\n"
    "          <span>{initials}</span>\n"
    "        ) : (\n"
    "          <svg\n"
    '            aria-hidden="true"\n'
    "            width={cfg.dimension * 0.6}\n"
    "            height={cfg.dimension * 0.6}\n"
    '            viewBox="0 0 24 24"\n'
    '            fill="none"\n'
    '            stroke="currentColor"\n'
    '            strokeWidth="2"\n'
    '            strokeLinecap="round"\n'
    '            strokeLinejoin="round"\n'
    "          >\n"
    '            <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />\n'
    '            <circle cx="12" cy="7" r="4" />\n'
    "          </svg>\n"
    "        )}\n"
    "      </div>\n\n"
    "      {status && (\n"
    "        <span\n"
    '          aria-hidden="true"\n'
    "          style={{\n"
    '            position: "absolute",\n'
    "            width: cfg.statusSize,\n"
    "            height: cfg.statusSize,\n"
    '            borderRadius: "50%",\n'
    "            backgroundColor: statusColors[status],\n"
    '            border: "2px solid #ffffff",\n'
    '            boxSizing: "content-box",\n'
    "            ...statusPositions[statusPosition],\n"
    "          }}\n"
    "        />\n"
    "      )}\n"
    "    </div>\n"
    "  );\n"
    "}\n\n"
    "export function AvatarGroup({\n"
    "  children,\n"
    "  max = 4,\n"
    '  size = "md",\n'
    '  shape = "circle",\n'
    "  spacing = -8,\n"
    "  className,\n"
    "  style,\n"
    "}: AvatarGroupProps) {\n"
    "  const childArray = React.Children.toArray(children);\n"
    "  const visibleAvatars = childArray.slice(0, max);\n"
    "  const excessCount = childArray.length - max;\n"
    "  const cfg = sizeMap[size];\n"
    "  const borderRadius = shapeBorderRadius[shape];\n\n"
    "  return (\n"
    "    <div\n"
    '      role="group"\n'
    "      aria-label={`Group of ${childArray.length} members`}\n"
    "      className={className}\n"
    "      style={{\n"
    '        display: "inline-flex",\n'
    '        alignItems: "center",\n'
    '        flexDirection: "row",\n'
    "        ...style,\n"
    "      }}\n"
    "    >\n"
    "      {visibleAvatars.map((child, index) => {\n"
    "        return (\n"
    "          <div\n"
    "            key={index}\n"
    "            style={{\n"
    "              marginLeft: index === 0 ? 0 : spacing,\n"
    '              boxShadow: "0 0 0 2px #ffffff",\n'
    "              borderRadius,\n"
    "              zIndex: visibleAvatars.length - index,\n"
    "            }}\n"
    "          >\n"
    "            {React.isValidElement(child)\n"
    "              ? React.cloneElement(child as React.ReactElement<any>, {\n"
    "                  size: (child.props as any).size || size,\n"
    "                  shape: (child.props as any).shape || shape,\n"
    "                })\n"
    "              : child}\n"
    "          </div>\n"
    "        );\n"
    "      })}\n\n"
    "      {excessCount > 0 && (\n"
    "        <div\n"
    "          style={{\n"
    "            marginLeft: spacing,\n"
    "            width: cfg.dimension,\n"
    "            height: cfg.dimension,\n"
    "            borderRadius,\n"
    '            backgroundColor: "#f1f5f9",\n'
    '            color: "#475569",\n'
    "            fontWeight: 600,\n"
    "            fontSize: cfg.fontSize,\n"
    '            display: "inline-flex",\n'
    '            alignItems: "center",\n'
    '            justifyContent: "center",\n'
    '            boxShadow: "0 0 0 2px #ffffff",\n'
    "            zIndex: 0,\n"
    "          }}\n"
    "        >\n"
    "          +{excessCount}\n"
    "        </div>\n"
    "      )}\n"
    "    </div>\n"
    "  );\n"
    "}\n\n"
    "export default Avatar;\n"
)


def render_avatar_component() -> str:
    """Return the static TypeScript implementation of the Avatar component."""
    return _AVATAR_COMPONENT


# --- Toggle Switch primitive (R-320) -------------------------------------------------------------
_TOGGLE_COMPONENT = (
    '"use client";\n\n'
    'import React, { useState, useId } from "react";\n\n'
    'export type ToggleSize = "sm" | "md" | "lg";\n\n'
    "export interface ToggleProps {\n"
    "  checked?: boolean;\n"
    "  defaultChecked?: boolean;\n"
    "  onChange?: (checked: boolean) => void;\n"
    "  disabled?: boolean;\n"
    "  size?: ToggleSize;\n"
    "  label?: React.ReactNode;\n"
    "  description?: React.ReactNode;\n"
    "  id?: string;\n"
    "  name?: string;\n"
    "  required?: boolean;\n"
    "  ariaLabel?: string;\n"
    "  ariaDescribedBy?: string;\n"
    "  style?: React.CSSProperties;\n"
    "  className?: string;\n"
    "}\n\n"
    "const SIZE_CONFIG: Record<\n"
    "  ToggleSize,\n"
    "  {\n"
    "    trackWidth: number;\n"
    "    trackHeight: number;\n"
    "    thumbSize: number;\n"
    "    translate: number;\n"
    "    fontSize: number;\n"
    "    descriptionSize: number;\n"
    "  }\n"
    "> = {\n"
    "  sm: {\n"
    "    trackWidth: 32,\n"
    "    trackHeight: 18,\n"
    "    thumbSize: 14,\n"
    "    translate: 14,\n"
    "    fontSize: 13,\n"
    "    descriptionSize: 11,\n"
    "  },\n"
    "  md: {\n"
    "    trackWidth: 44,\n"
    "    trackHeight: 24,\n"
    "    thumbSize: 20,\n"
    "    translate: 20,\n"
    "    fontSize: 14,\n"
    "    descriptionSize: 12,\n"
    "  },\n"
    "  lg: {\n"
    "    trackWidth: 56,\n"
    "    trackHeight: 30,\n"
    "    thumbSize: 26,\n"
    "    translate: 26,\n"
    "    fontSize: 16,\n"
    "    descriptionSize: 13,\n"
    "  },\n"
    "};\n\n"
    "export function Toggle({\n"
    "  checked,\n"
    "  defaultChecked = false,\n"
    "  onChange,\n"
    "  disabled = false,\n"
    '  size = "md",\n'
    "  label,\n"
    "  description,\n"
    "  id: customId,\n"
    "  name,\n"
    "  required = false,\n"
    "  ariaLabel,\n"
    "  ariaDescribedBy,\n"
    "  style,\n"
    "  className,\n"
    "}: ToggleProps) {\n"
    "  const generatedId = useId();\n"
    '  const toggleId = customId || `toggle-${generatedId}`;\n'
    '  const labelId = `${toggleId}-label`;\n'
    '  const descId = `${toggleId}-desc`;\n\n'
    "  const isControlled = checked !== undefined;\n"
    "  const [internalChecked, setInternalChecked] = useState<boolean>(defaultChecked);\n"
    "  const isChecked = isControlled ? Boolean(checked) : internalChecked;\n\n"
    "  const config = SIZE_CONFIG[size] || SIZE_CONFIG.md;\n\n"
    "  const handleToggle = () => {\n"
    "    if (disabled) return;\n"
    "    const nextState = !isChecked;\n"
    "    if (!isControlled) {\n"
    "      setInternalChecked(nextState);\n"
    "    }\n"
    "    onChange?.(nextState);\n"
    "  };\n\n"
    "  const handleKeyDown = (e: React.KeyboardEvent) => {\n"
    "    if (disabled) return;\n"
    '    if (e.key === " " || e.key === "Spacebar" || e.key === "Enter") {\n'
    "      e.preventDefault();\n"
    "      handleToggle();\n"
    "    }\n"
    "  };\n\n"
    "  const trackStyle: React.CSSProperties = {\n"
    '    position: "relative",\n'
    '    display: "inline-block",\n'
    "    width: config.trackWidth,\n"
    "    height: config.trackHeight,\n"
    '    backgroundColor: isChecked ? "#2563eb" : "#cbd5e1",\n'
    "    borderRadius: config.trackHeight / 2,\n"
    '    cursor: disabled ? "not-allowed" : "pointer",\n'
    '    transition: "background-color 0.2s ease, opacity 0.2s ease",\n'
    "    opacity: disabled ? 0.5 : 1,\n"
    "    flexShrink: 0,\n"
    '    outline: "none",\n'
    '    border: "2px solid transparent",\n'
    '    boxSizing: "border-box",\n'
    "  };\n\n"
    "  const thumbStyle: React.CSSProperties = {\n"
    '    position: "absolute",\n'
    "    top: (config.trackHeight - 4 - config.thumbSize) / 2,\n"
    "    left: 2,\n"
    "    width: config.thumbSize,\n"
    "    height: config.thumbSize,\n"
    '    backgroundColor: "#ffffff",\n'
    '    borderRadius: "50%",\n'
    '    boxShadow: "0 1px 3px 0 rgba(0, 0, 0, 0.2), 0 1px 2px 0 rgba(0, 0, 0, 0.06)",\n'
    '    transition: "transform 0.2s ease",\n'
    '    transform: isChecked ? `translateX(${config.translate}px)` : "translateX(0px)",\n'
    '    pointerEvents: "none",\n'
    "  };\n\n"
    "  return (\n"
    "    <div\n"
    "      style={{\n"
    '        display: "inline-flex",\n'
    '        alignItems: description ? "flex-start" : "center",\n'
    "        gap: 10,\n"
    "        opacity: disabled ? 0.6 : 1,\n"
    "        ...style,\n"
    "      }}\n"
    "      className={className}\n"
    "    >\n"
    "      <div\n"
    "        id={toggleId}\n"
    '        role="switch"\n'
    "        aria-checked={isChecked}\n"
    "        aria-disabled={disabled}\n"
    "        aria-required={required}\n"
    "        aria-label={ariaLabel}\n"
    "        aria-labelledby={label ? labelId : undefined}\n"
    "        aria-describedby={description ? descId : (ariaDescribedBy || undefined)}\n"
    "        tabIndex={disabled ? -1 : 0}\n"
    "        onClick={handleToggle}\n"
    "        onKeyDown={handleKeyDown}\n"
    "        style={trackStyle}\n"
    "      >\n"
    '        <span style={thumbStyle} aria-hidden="true" />\n'
    "      </div>\n\n"
    "      {name && (\n"
    "        <input\n"
    '          type="hidden"\n'
    "          name={name}\n"
    '          value={isChecked ? "true" : "false"}\n'
    "        />\n"
    "      )}\n\n"
    "      {(label || description) && (\n"
    "        <div\n"
    "          style={{\n"
    '            display: "flex",\n'
    '            flexDirection: "column",\n'
    '            cursor: disabled ? "not-allowed" : "pointer",\n'
    '            userSelect: "none",\n'
    "          }}\n"
    "          onClick={handleToggle}\n"
    "        >\n"
    "          {label && (\n"
    "            <span\n"
    "              id={labelId}\n"
    "              style={{\n"
    "                fontSize: config.fontSize,\n"
    "                fontWeight: 500,\n"
    '                color: disabled ? "#94a3b8" : "#0f172a",\n'
    "                lineHeight: 1.4,\n"
    "              }}\n"
    "            >\n"
    "              {label}\n"
    "            </span>\n"
    "          )}\n"
    "          {description && (\n"
    "            <span\n"
    "              id={descId}\n"
    "              style={{\n"
    "                fontSize: config.descriptionSize,\n"
    '                color: "#64748b",\n'
    "                marginTop: 2,\n"
    "                lineHeight: 1.4,\n"
    "              }}\n"
    "            >\n"
    "              {description}\n"
    "            </span>\n"
    "          )}\n"
    "        </div>\n"
    "      )}\n"
    "    </div>\n"
    "  );\n"
    "}\n\n"
    "export const ToggleSwitch = Toggle;\n"
    "export default Toggle;\n"
)


def render_toggle_component() -> str:
    """Return the static TypeScript implementation of the Toggle component."""
    return _TOGGLE_COMPONENT


