    "export const ContextMenuSub = function ContextMenuSub({ children, open: controlledOpen, onOpenChange }: ContextMenuSubProps) {\n"
    "  const [internalOpen, setInternalOpen] = useState(false);\n"
    "  const triggerRef = useRef<HTMLDivElement | null>(null);\n"
