    "    </ContextMenuSubContext.Provider>\n"
    "  );\n"
    "};\n"
    "\n"
    "export const ContextMenuSubTrigger = forwardRef<HTMLDivElement, ContextMenuSubTriggerProps>(\n"
    "  function ContextMenuSubTrigger({ children, disabled = false, icon, className, style, ...rest }, ref) {\n"
    "    const subCtx = useContext(ContextMenuSubContext);\n"
