    "        </div>\n"
    "        <svg\n"
    "          width=\"14\"\n"
    "          height=\"14\"\n"
    "          viewBox=\"0 0 24 24\"\n"
    "          fill=\"none\"\n"
    "          stroke=\"currentColor\"\n"
    "          strokeWidth=\"2\"\n"
