    "\n"
    "export const ContextMenuSubContent = forwardRef<HTMLDivElement, ContextMenuSubContentProps>(\n"
    "  function ContextMenuSubContent({ children, className, style, ...rest }, ref) {\n"
    "    const subCtx = useContext(ContextMenuSubContext);\n"
    "    const { variant, size } = useContextMenu();\n"
    "\n"
    "    if (!subCtx?.open) return null;\n"
    "\n"
    "    const sizeStyles = {\n"
    "      sm: { minWidth: \"150px\", padding: \"4px\", fontSize: \"12px\", borderRadius: \"8px\" },\n"
    "      md: { minWidth: \"180px\", padding: \"6px\", fontSize: \"13px\", borderRadius: \"10px\" },\n"
    "      lg: { minWidth: \"210px\", padding: \"8px\", fontSize: \"14px\", borderRadius: \"12px\" },\n"
    "    }[size];\n"
    "\n"
    "    let variantStyles: CSSProperties = {};\n"
    "    if (variant === \"neon\") {\n"
    "      variantStyles = {\n"
    "        background: \"rgba(15, 23, 42, 0.95)\",\n"
    "        border: \"1px solid rgba(6, 182, 212, 0.4)\",\n"
    "        boxShadow: \"0 0 20px rgba(6, 182, 212, 0.25), 0 8px 32px rgba(0, 0, 0, 0.6)\",\n"
    "        color: \"#f8fafc\",\n"
    "      };\n"
    "    } else if (variant === \"glass\") {\n"
    "      variantStyles = {\n"
    "        background: \"rgba(255, 255, 255, 0.18)\",\n"
    "        backdropFilter: \"blur(16px)\",\n"
    "        WebkitBackdropFilter: \"blur(16px)\",\n"
    "        border: \"1px solid rgba(255, 255, 255, 0.3)\",\n"
    "        boxShadow: \"0 8px 32px rgba(0, 0, 0, 0.25)\",\n"
    "        color: \"inherit\",\n"
    "      };\n"
    "    } else if (variant === \"bordered\") {\n"
    "      variantStyles = {\n"
    "        background: \"var(--color-surface, #ffffff)\",\n"
    "        border: \"1.5px solid var(--color-border, #e2e8f0)\",\n"
    "        boxShadow: \"0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)\",\n"
    "        color: \"var(--color-text, #0f172a)\",\n"
    "      };\n"
    "    } else {\n"
    "      variantStyles = {\n"
    "        background: \"var(--color-surface, #ffffff)\",\n"
    "        border: \"none\",\n"
    "        boxShadow: \"0 4px 20px rgba(0, 0, 0, 0.12)\",\n"
    "        color: \"var(--color-text, #0f172a)\",\n"
    "      };\n"
    "    }\n"
    "\n"
    "    const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {\n"
    "      if (e.key === \"ArrowLeft\") {\n"
    "        e.preventDefault();\n"
