    '            border: isChecked ? "1px solid #0f172a" : "1px solid #cbd5e1",\n'
    '            background: isChecked ? "#0f172a" : "#ffffff",\n'
    '            color: isChecked ? "#ffffff" : "#334155",\n'
    '            fontSize,\n'
    '            fontWeight: 500,\n'
    '            cursor: isDisabled ? "not-allowed" : "pointer",\n'
    '            opacity: isDisabled ? 0.5 : 1,\n'
    '            transition: "all 0.15s ease",\n'
    '            outline: "none",\n'
    '            whiteSpace: "nowrap",\n'
    '            ...style,\n'
    '          }}\n'
    '          className={className}\n'
    '          {...rest}\n'
    '        >\n'
    '          {label || children}\n'
    '        </button>\n'
    '      );\n'
    '    }\n\n'
    '    if (ctx.variant === "neon") {\n'
    '      return (\n'
    '        <button\n'
    '          ref={setRefs}\n'
    '          type="button"\n'
    '          role="radio"\n'
    '          aria-checked={isChecked}\n'
    '          aria-disabled={isDisabled || undefined}\n'
    '          disabled={isDisabled}\n'
    '          data-state={isChecked ? "checked" : "unchecked"}\n'
    '          data-variant={ctx.variant}\n'
    '          data-size={ctx.size}\n'
    '          onClick={handleClick}\n'
    '          onKeyDown={onKeyDown}\n'
    '          style={{\n'
    '            display: "inline-flex",\n'
    '            alignItems: "center",\n'
    '            gap: "10px",\n'
    '            padding: ctx.size === "sm" ? "4px 8px" : ctx.size === "lg" ? "8px 12px" : "6px 10px",\n'
    '            borderRadius: "6px",\n'
    '            border: "none",\n'
    '            background: "transparent",\n'
    '            color: isChecked ? "#38bdf8" : "#94a3b8",\n'
    '            cursor: isDisabled ? "not-allowed" : "pointer",\n'
    '            opacity: isDisabled ? 0.5 : 1,\n'
    '            transition: "all 0.15s ease",\n'
    '            outline: "none",\n'
    '            textAlign: "left",\n'
