    '}\n'
    '\n'
    'function getVariantStyles(variant: MarkdownEditorVariant): VariantStyles {\n'
    '  switch (variant) {\n'
    '    case "card":\n'
    '      return {\n'
    '        containerBorder: "1px solid rgba(255, 255, 255, 0.1)",\n'
    '        containerBg: "#0f172a",\n'
