    '        toolbarBg: "rgba(255, 255, 255, 0.05)",\n'
    '        toolbarBorder: "1px solid rgba(255, 255, 255, 0.1)",\n'
    '        toolbarDivider: "rgba(255, 255, 255, 0.12)",\n'
    '        buttonColor: "#cbd5e1",\n'
    '        buttonHoverBg: "rgba(255, 255, 255, 0.1)",\n'
    '        buttonActiveBg: "rgba(14, 165, 233, 0.25)",\n'
    '        buttonActiveColor: "#38bdf8",\n'
    '        editorText: "#f8fafc",\n'
