    "      </div>\n\n"
    "      {/* Right: Undo/Redo, Zoom, Clear, Export */}\n"
    "      <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>\n"
    "        {/* Undo */}\n"
    "        <button\n"
    "          type=\"button\"\n"
    "          aria-label=\"Undo\"\n"
    "          disabled={!canUndo}\n"
