_SLUG_INPUT_COMPONENT = r"""'use client';

import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react';
import type { CSSProperties } from 'react';

export type SlugInputVariant = 'default' | 'card' | 'glass' | 'neon';
export type SlugInputSize = 'sm' | 'md' | 'lg';

export interface SlugInputProps {
  value?: string;
  defaultValue?: string;
  source?: string;
  autoSyncFromSource?: boolean;
  prefix?: string;
  separator?: string;
  maxLength?: number;
  label?: string;
  placeholder?: string;
  name?: string;
  disabled?: boolean;
  showLabel?: boolean;
  showPrefix?: boolean;
  showCopy?: boolean;
  variant?: SlugInputVariant;
  size?: SlugInputSize;
  accentColor?: string;
  ariaLabel?: string;
  className?: string;
  style?: CSSProperties;
  onChange?: (slug: string) => void;
  onCopy?: (fullUrl: string) => void;
}

export interface SlugInputHandle {
  getValue: () => string;
  getFullUrl: () => string;
  setValue: (value: string) => void;
  slugify: (text: string) => string;
  clear: () => void;
  focus: () => void;
}

interface VariantStyle {
  wrapper: CSSProperties;
  labelColor: string;
  mutedColor: string;
  inputBg: string;
  inputColor: string;
  inputBorder: string;
  focusBorder: string;
  prefixBg: string;
}

const VARIANT_STYLES: Record<SlugInputVariant, VariantStyle> = {
  default: {
    wrapper: { background: 'transparent' },
    labelColor: '#0f172a', mutedColor: '#64748b', inputBg: '#ffffff', inputColor: '#0f172a', inputBorder: '#cbd5e1', focusBorder: '#2563eb', prefixBg: '#f1f5f9',
  },
  card: {
    wrapper: { background: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '12px', boxShadow: '0 4px 16px rgba(0, 0, 0, 0.06)', padding: '16px' },
    labelColor: '#0f172a', mutedColor: '#64748b', inputBg: '#ffffff', inputColor: '#0f172a', inputBorder: '#cbd5e1', focusBorder: '#2563eb', prefixBg: '#f1f5f9',
  },
  glass: {
    wrapper: { background: 'rgba(248, 250, 252, 0.6)', border: '1px solid rgba(255, 255, 255, 0.4)', borderRadius: '12px', boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)', backdropFilter: 'blur(16px)', WebkitBackdropFilter: 'blur(16px)', padding: '16px' },
    labelColor: '#0f172a', mutedColor: '#475569', inputBg: 'rgba(255, 255, 255, 0.7)', inputColor: '#0f172a', inputBorder: 'rgba(148, 163, 184, 0.6)', focusBorder: '#2563eb', prefixBg: 'rgba(241, 245, 249, 0.7)',
  },
  neon: {
    wrapper: { background: '#050811', border: '1px solid rgba(6, 182, 212, 0.4)', borderRadius: '12px', boxShadow: '0 0 24px rgba(6, 182, 212, 0.15)', padding: '16px' },
    labelColor: '#f8fafc', mutedColor: '#38bdf8', inputBg: 'rgba(6, 182, 212, 0.08)', inputColor: '#e0f2fe', inputBorder: 'rgba(6, 182, 212, 0.5)', focusBorder: '#06b6d4', prefixBg: 'rgba(6, 182, 212, 0.12)',
  },
};

const SIZE_STYLES: Record<SlugInputSize, { font: number; pad: number }> = {
  sm: { font: 13, pad: 8 },
  md: { font: 15, pad: 10 },
  lg: { font: 17, pad: 13 },
};

function slugify(text: string, separator: string): string {
  const sep = separator || '-';
  let s = text.normalize('NFKD').split('').filter((c) => { const code = c.charCodeAt(0); return code < 0x300 || code > 0x36f; }).join('');
  s = s.toLowerCase().replace(/[^a-z0-9]+/g, sep);
  while (s.length > 0 && s.slice(0, sep.length) === sep) s = s.slice(sep.length);
  while (s.length > 0 && s.slice(s.length - sep.length) === sep) s = s.slice(0, s.length - sep.length);
  return s;
}

const SlugInputComponent = forwardRef<SlugInputHandle, SlugInputProps>(
  function SlugInput(
    {
      value,
      defaultValue = '',
      source,
      autoSyncFromSource = true,
      prefix = '',
      separator = '-',
      maxLength,
      label = 'Slug',
      placeholder = 'my-page-slug',
      name,
      disabled = false,
      showLabel = true,
      showPrefix = true,
      showCopy = true,
      variant = 'default',
      size = 'md',
      accentColor,
      ariaLabel = 'URL slug',
      className,
      style,
      onChange,
      onCopy,
    }: SlugInputProps,
    ref,
  ) {
    const isControlled = typeof value === 'string';
    const [internal, setInternal] = useState<string>(() => slugify(defaultValue, separator));
    const [copied, setCopied] = useState(false);
    const [focused, setFocused] = useState(false);
    const editedRef = useRef<boolean>(Boolean(defaultValue));
    const inputRef = useRef<HTMLInputElement | null>(null);

    const currentSlug = isControlled ? (value as string) : internal;
    const clip = (s: string) => (typeof maxLength === 'number' ? s.slice(0, maxLength) : s);
    const fullUrl = prefix + currentSlug;

    const emit = (nextSlug: string) => {
      const clipped = clip(nextSlug);
      if (!isControlled) setInternal(clipped);
      if (onChange) onChange(clipped);
    };

    useEffect(() => {
      if (autoSyncFromSource && !editedRef.current && typeof source === 'string') {
        const derived = clip(slugify(source, separator));
        if (!isControlled) setInternal(derived);
        if (onChange) onChange(derived);
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [source, autoSyncFromSource, separator]);

    const handleChange = (raw: string) => {
      editedRef.current = true;
      emit(slugify(raw, separator));
    };

    const doCopy = () => {
      if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(fullUrl).catch(() => undefined);
      }
      setCopied(true);
      if (onCopy) onCopy(fullUrl);
      window.setTimeout(() => setCopied(false), 1500);
    };

    useImperativeHandle(
      ref,
      () => ({
        getValue: () => currentSlug,
        getFullUrl: () => fullUrl,
        setValue: (v: string) => {
          editedRef.current = true;
          emit(slugify(v, separator));
        },
        slugify: (text: string) => slugify(text, separator),
        clear: () => {
          editedRef.current = false;
          if (!isControlled) setInternal('');
          if (onChange) onChange('');
        },
        focus: () => {
          if (inputRef.current) inputRef.current.focus();
        },
      }),
      [currentSlug, fullUrl, isControlled, separator, onChange],
    );

    const theme = VARIANT_STYLES[variant] || VARIANT_STYLES.default;
    const sizing = SIZE_STYLES[size] || SIZE_STYLES.md;
    const resolvedAccent = accentColor || theme.focusBorder;

    return (
      <div
        className={className}
        data-variant={variant}
        data-size={size}
        style={{ display: 'flex', flexDirection: 'column', gap: '4px', fontFamily: 'system-ui, -apple-system, sans-serif', ...theme.wrapper, ...style }}
      >
        {showLabel ? (
          <label style={{ fontSize: (sizing.font - 2) + 'px', fontWeight: 600, color: theme.labelColor }}>{label}</label>
        ) : null}
        <div style={{ display: 'flex', alignItems: 'stretch', border: '1px solid ' + (focused ? resolvedAccent : theme.inputBorder), borderRadius: '8px', overflow: 'hidden', background: theme.inputBg }}>
          {showPrefix && prefix ? (
            <span style={{ display: 'flex', alignItems: 'center', padding: '0 ' + sizing.pad + 'px', background: theme.prefixBg, color: theme.mutedColor, fontSize: (sizing.font - 1) + 'px', fontFamily: 'monospace', whiteSpace: 'nowrap' }}>
              {prefix}
            </span>
          ) : null}
          <input
            ref={inputRef}
            type="text"
            value={currentSlug}
            name={name}
            disabled={disabled}
            placeholder={placeholder}
            aria-label={ariaLabel}
            spellCheck={false}
            autoComplete="off"
            onChange={(e) => handleChange(e.target.value)}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            style={{
              flex: 1,
              fontSize: sizing.font + 'px',
              padding: sizing.pad + 'px',
              background: 'transparent',
              color: theme.inputColor,
              border: 'none',
              outline: 'none',
              fontFamily: 'monospace',
              minWidth: 0,
            }}
          />
          {showCopy ? (
            <button
              type="button"
              aria-label="Copy URL"
              onClick={doCopy}
              disabled={disabled}
              style={{ padding: '0 ' + sizing.pad + 'px', background: 'transparent', border: 'none', borderLeft: '1px solid ' + theme.inputBorder, color: resolvedAccent, cursor: disabled ? 'default' : 'pointer', fontSize: (sizing.font - 1) + 'px', fontWeight: 600, whiteSpace: 'nowrap' }}
            >
              {copied ? 'Copied' : 'Copy'}
            </button>
          ) : null}
        </div>
        <span aria-live="polite" style={{ position: 'absolute', width: '1px', height: '1px', overflow: 'hidden', clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', whiteSpace: 'nowrap' }}>
          {copied ? 'URL copied to clipboard' : ''}
        </span>
      </div>
    );
  },
);

SlugInputComponent.displayName = 'SlugInput';

export const SlugInput = SlugInputComponent;
export const Slugify = SlugInputComponent;
export const UrlSlugInput = SlugInputComponent;
export const PermalinkInput = SlugInputComponent;

SlugInput.displayName = 'SlugInput';
Slugify.displayName = 'Slugify';
UrlSlugInput.displayName = 'UrlSlugInput';
PermalinkInput.displayName = 'PermalinkInput';

export default SlugInputComponent;
"""


def render_slug_input_component() -> str:
    """Render the Accessible Futuristic Reusable Slug / URL Input Suite (R-411)."""
    return _SLUG_INPUT_COMPONENT


_CHARACTER_COUNTER_COMPONENT = r"""'use client';

import { forwardRef, useImperativeHandle, useRef, useState } from 'react';
import type { CSSProperties } from 'react';

export type CharacterCounterVariant = 'default' | 'card' | 'glass' | 'neon';
export type CharacterCounterSize = 'sm' | 'md' | 'lg';

export interface CharacterCounterStats {
  characters: number;
  words: number;
  remaining: number | null;
  overLimit: boolean;
}

export interface CharacterCounterProps {
  value?: string;
  defaultValue?: string;
  maxLength?: number;
  maxWords?: number;
  countWords?: boolean;
  hardLimit?: boolean;
  warnThreshold?: number;
  showProgress?: boolean;
  showWords?: boolean;
  rows?: number;
  label?: string;
  placeholder?: string;
  name?: string;
  disabled?: boolean;
  showLabel?: boolean;
  variant?: CharacterCounterVariant;
  size?: CharacterCounterSize;
  accentColor?: string;
  ariaLabel?: string;
  className?: string;
  style?: CSSProperties;
  onChange?: (value: string, stats: CharacterCounterStats) => void;
}

export interface CharacterCounterHandle {
  getValue: () => string;
  setValue: (value: string) => void;
  getStats: () => CharacterCounterStats;
  clear: () => void;
  focus: () => void;
}

interface VariantStyle {
  wrapper: CSSProperties;
  labelColor: string;
  mutedColor: string;
  inputBg: string;
  inputColor: string;
  inputBorder: string;
  focusBorder: string;
  trackBg: string;
  okColor: string;
  warnColor: string;
  overColor: string;
}

const VARIANT_STYLES: Record<CharacterCounterVariant, VariantStyle> = {
  default: {
    wrapper: { background: 'transparent' },
    labelColor: '#0f172a', mutedColor: '#64748b', inputBg: '#ffffff', inputColor: '#0f172a', inputBorder: '#cbd5e1', focusBorder: '#2563eb',
    trackBg: '#e2e8f0', okColor: '#2563eb', warnColor: '#f59e0b', overColor: '#dc2626',
  },
  card: {
    wrapper: { background: '#ffffff', border: '1px solid #e2e8f0', borderRadius: '12px', boxShadow: '0 4px 16px rgba(0, 0, 0, 0.06)', padding: '16px' },
    labelColor: '#0f172a', mutedColor: '#64748b', inputBg: '#ffffff', inputColor: '#0f172a', inputBorder: '#cbd5e1', focusBorder: '#2563eb',
    trackBg: '#e2e8f0', okColor: '#2563eb', warnColor: '#f59e0b', overColor: '#dc2626',
  },
  glass: {
    wrapper: { background: 'rgba(248, 250, 252, 0.6)', border: '1px solid rgba(255, 255, 255, 0.4)', borderRadius: '12px', boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)', backdropFilter: 'blur(16px)', WebkitBackdropFilter: 'blur(16px)', padding: '16px' },
    labelColor: '#0f172a', mutedColor: '#475569', inputBg: 'rgba(255, 255, 255, 0.7)', inputColor: '#0f172a', inputBorder: 'rgba(148, 163, 184, 0.6)', focusBorder: '#2563eb',
    trackBg: 'rgba(148, 163, 184, 0.35)', okColor: '#2563eb', warnColor: '#d97706', overColor: '#dc2626',
  },
  neon: {
    wrapper: { background: '#050811', border: '1px solid rgba(6, 182, 212, 0.4)', borderRadius: '12px', boxShadow: '0 0 24px rgba(6, 182, 212, 0.15)', padding: '16px' },
    labelColor: '#f8fafc', mutedColor: '#38bdf8', inputBg: 'rgba(6, 182, 212, 0.08)', inputColor: '#e0f2fe', inputBorder: 'rgba(6, 182, 212, 0.5)', focusBorder: '#06b6d4',
    trackBg: 'rgba(6, 182, 212, 0.12)', okColor: '#06b6d4', warnColor: '#fbbf24', overColor: '#fb7185',
  },
};

const SIZE_STYLES: Record<CharacterCounterSize, { font: number; pad: number; bar: number }> = {
  sm: { font: 13, pad: 8, bar: 4 },
  md: { font: 15, pad: 10, bar: 6 },
  lg: { font: 17, pad: 13, bar: 8 },
};

function countCharacters(text: string): number {
  return Array.from(text).length;
}

function countWordsIn(text: string): number {
  const trimmed = text.trim();
  if (!trimmed) return 0;
  return trimmed.split(/\s+/).length;
}

function computeStats(text: string, maxLength?: number): CharacterCounterStats {
  const characters = countCharacters(text);
  const words = countWordsIn(text);
  const remaining = typeof maxLength === 'number' ? maxLength - characters : null;
  const overLimit = typeof maxLength === 'number' ? characters > maxLength : false;
  return { characters: characters, words: words, remaining: remaining, overLimit: overLimit };
}

const CharacterCounterComponent = forwardRef<CharacterCounterHandle, CharacterCounterProps>(
  function CharacterCounter(
    {
      value,
      defaultValue = '',
      maxLength,
      maxWords,
      countWords = true,
      hardLimit = false,
      warnThreshold = 0.9,
      showProgress = true,
      showWords = true,
      rows = 4,
      label = 'Message',
      placeholder = '',
      name,
      disabled = false,
      showLabel = true,
      variant = 'default',
      size = 'md',
      accentColor,
      ariaLabel = 'Text with character counter',
      className,
      style,
      onChange,
    }: CharacterCounterProps,
    ref,
  ) {
    const isControlled = typeof value === 'string';
    const [internal, setInternal] = useState<string>(defaultValue);
    const textareaRef = useRef<HTMLTextAreaElement | null>(null);
    const counterId = useRef<string>('char-counter-status').current;

    const current = isControlled ? (value as string) : internal;
    const stats = computeStats(current, maxLength);
    const wordsOver = typeof maxWords === 'number' && stats.words > maxWords;

    const emit = (next: string) => {
      let text = next;
      if (hardLimit && typeof maxLength === 'number') {
        const chars = Array.from(text);
        if (chars.length > maxLength) text = chars.slice(0, maxLength).join('');
      }
      if (!isControlled) setInternal(text);
      if (onChange) onChange(text, computeStats(text, maxLength));
    };

    useImperativeHandle(
      ref,
      () => ({
        getValue: () => current,
        setValue: (v: string) => emit(v),
        getStats: () => computeStats(current, maxLength),
        clear: () => emit(''),
        focus: () => {
          if (textareaRef.current) textareaRef.current.focus();
        },
      }),
      [current, isControlled, maxLength, hardLimit, onChange],
    );

    const theme = VARIANT_STYLES[variant] || VARIANT_STYLES.default;
    const sizing = SIZE_STYLES[size] || SIZE_STYLES.md;

    const ratio = typeof maxLength === 'number' && maxLength > 0 ? stats.characters / maxLength : 0;
    const isWarn = ratio >= warnThreshold && !stats.overLimit;
    const barColor = stats.overLimit || wordsOver ? theme.overColor : isWarn ? theme.warnColor : (accentColor || theme.okColor);
    const countColor = stats.overLimit || wordsOver ? theme.overColor : isWarn ? theme.warnColor : theme.mutedColor;

    return (
      <div
        className={className}
        data-variant={variant}
        data-size={size}
        style={{ display: 'flex', flexDirection: 'column', gap: '4px', fontFamily: 'system-ui, -apple-system, sans-serif', ...theme.wrapper, ...style }}
      >
        {showLabel ? (
          <label style={{ fontSize: (sizing.font - 2) + 'px', fontWeight: 600, color: theme.labelColor }}>{label}</label>
        ) : null}
        <textarea
          ref={textareaRef}
          value={current}
          name={name}
          rows={rows}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={ariaLabel}
          aria-describedby={counterId}
          aria-invalid={stats.overLimit || wordsOver || undefined}
          onChange={(e) => emit(e.target.value)}
          style={{
            width: '100%',
            boxSizing: 'border-box',
            fontSize: sizing.font + 'px',
            padding: sizing.pad + 'px',
            background: theme.inputBg,
            color: theme.inputColor,
            border: '1px solid ' + (stats.overLimit || wordsOver ? theme.overColor : theme.inputBorder),
            borderRadius: '8px',
            outline: 'none',
            resize: 'vertical',
            fontFamily: 'inherit',
            lineHeight: 1.5,
          }}
        />
        {showProgress && typeof maxLength === 'number' ? (
          <div style={{ height: sizing.bar + 'px', borderRadius: '999px', background: theme.trackBg, overflow: 'hidden' }} aria-hidden="true">
            <div style={{ width: Math.min(100, Math.round(ratio * 100)) + '%', height: '100%', background: barColor, transition: 'width 0.15s ease, background 0.15s ease' }} />
          </div>
        ) : null}
        <div
          id={counterId}
          role="status"
          aria-live="polite"
          style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', fontSize: (sizing.font - 3) + 'px', color: countColor, fontVariantNumeric: 'tabular-nums' }}
        >
          <span>
            {countWords && showWords ? (stats.words + (stats.words === 1 ? ' word' : ' words') + (typeof maxWords === 'number' ? ' / ' + maxWords : '') + ' · ') : ''}
            {stats.characters}
            {typeof maxLength === 'number' ? ' / ' + maxLength : ' characters'}
          </span>
          {typeof maxLength === 'number' ? (
            <span style={{ fontWeight: 600 }}>
              {stats.overLimit ? Math.abs(stats.remaining as number) + ' over' : (stats.remaining as number) + ' left'}
            </span>
          ) : null}
        </div>
      </div>
    );
  },
);

CharacterCounterComponent.displayName = 'CharacterCounter';

export const CharacterCounter = CharacterCounterComponent;
export const CharCounter = CharacterCounterComponent;
export const WordCounter = CharacterCounterComponent;
export const TextCounter = CharacterCounterComponent;

CharacterCounter.displayName = 'CharacterCounter';
CharCounter.displayName = 'CharCounter';
WordCounter.displayName = 'WordCounter';
TextCounter.displayName = 'TextCounter';

export default CharacterCounterComponent;
"""


def render_character_counter_component() -> str:
    """Render the Accessible Futuristic Reusable Character & Word Counter Textarea Suite (R-412)."""
    return _CHARACTER_COUNTER_COMPONENT


_COPY_BUTTON_COMPONENT = r"""'use client';

import { forwardRef, useImperativeHandle, useRef, useState } from 'react';
import type { CSSProperties, ReactNode } from 'react';

export type CopyButtonVariant = 'default' | 'card' | 'glass' | 'neon';
export type CopyButtonSize = 'sm' | 'md' | 'lg';

export interface CopyButtonProps {
  value: string;
  label?: string;
  copiedLabel?: string;
  showLabel?: boolean;
  showIcon?: boolean;
  timeout?: number;
  disabled?: boolean;
  variant?: CopyButtonVariant;
  size?: CopyButtonSize;
  accentColor?: string;
  ariaLabel?: string;
  className?: string;
  style?: CSSProperties;
  onCopy?: (value: string) => void;
  onError?: (error: unknown) => void;
}

export interface CopyButtonHandle {
  copy: () => void;
  isCopied: () => boolean;
  reset: () => void;
  focus: () => void;
}

interface VariantStyle {
  base: CSSProperties;
  color: string;
  copiedColor: string;
}

const VARIANT_STYLES: Record<CopyButtonVariant, VariantStyle> = {
  default: { base: { background: '#ffffff', border: '1px solid #cbd5e1' }, color: '#0f172a', copiedColor: '#16a34a' },
  card: { base: { background: '#f8fafc', border: '1px solid #e2e8f0', boxShadow: '0 1px 2px rgba(0, 0, 0, 0.05)' }, color: '#0f172a', copiedColor: '#16a34a' },
  glass: { base: { background: 'rgba(255, 255, 255, 0.6)', border: '1px solid rgba(255, 255, 255, 0.5)', backdropFilter: 'blur(12px)', WebkitBackdropFilter: 'blur(12px)' }, color: '#0f172a', copiedColor: '#16a34a' },
  neon: { base: { background: '#050811', border: '1px solid rgba(6, 182, 212, 0.5)', boxShadow: '0 0 16px rgba(6, 182, 212, 0.2)' }, color: '#38bdf8', copiedColor: '#22d3ee' },
};

const SIZE_STYLES: Record<CopyButtonSize, { font: number; pad: string; icon: number; gap: number }> = {
  sm: { font: 12, pad: '5px 10px', icon: 14, gap: 6 },
  md: { font: 14, pad: '7px 14px', icon: 16, gap: 8 },
  lg: { font: 16, pad: '9px 18px', icon: 18, gap: 10 },
};

async function writeClipboard(text: string): Promise<void> {
  if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
    await navigator.clipboard.writeText(text);
    return;
  }
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  const ok = document.execCommand('copy');
  document.body.removeChild(ta);
  if (!ok) throw new Error('copy command was rejected');
}

function CopyGlyph({ size }: { size: number }): ReactNode {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
      <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
    </svg>
  );
}

function CheckGlyph({ size }: { size: number }): ReactNode {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

const CopyButtonComponent = forwardRef<CopyButtonHandle, CopyButtonProps>(
  function CopyButton(
    {
      value,
      label = 'Copy',
      copiedLabel = 'Copied',
      showLabel = true,
      showIcon = true,
      timeout = 1500,
      disabled = false,
      variant = 'default',
      size = 'md',
      accentColor,
      ariaLabel,
      className,
      style,
      onCopy,
      onError,
    }: CopyButtonProps,
    ref,
  ) {
    const [copied, setCopied] = useState(false);
    const buttonRef = useRef<HTMLButtonElement | null>(null);
    const timerRef = useRef<number | null>(null);

    const isDisabled = disabled || !value;

    const runCopy = () => {
      if (isDisabled) return;
      writeClipboard(value)
        .then(() => {
          setCopied(true);
          if (onCopy) onCopy(value);
          if (timerRef.current !== null) window.clearTimeout(timerRef.current);
          timerRef.current = window.setTimeout(() => setCopied(false), timeout);
        })
        .catch((error) => {
          if (onError) onError(error);
        });
    };

    useImperativeHandle(
      ref,
      () => ({
        copy: () => runCopy(),
        isCopied: () => copied,
        reset: () => setCopied(false),
        focus: () => {
          if (buttonRef.current) buttonRef.current.focus();
        },
      }),
      [copied, value, isDisabled, timeout],
    );

    const theme = VARIANT_STYLES[variant] || VARIANT_STYLES.default;
    const sizing = SIZE_STYLES[size] || SIZE_STYLES.md;
    const currentColor = copied ? theme.copiedColor : (accentColor || theme.color);
    const text = copied ? copiedLabel : label;

    return (
      <button
        ref={buttonRef}
        type="button"
        onClick={runCopy}
        disabled={isDisabled}
        aria-label={ariaLabel || label}
        data-variant={variant}
        data-size={size}
        data-copied={copied ? 'true' : 'false'}
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: sizing.gap + 'px',
          padding: sizing.pad,
          fontSize: sizing.font + 'px',
          fontFamily: 'system-ui, -apple-system, sans-serif',
          fontWeight: 600,
          color: currentColor,
          borderRadius: '8px',
          cursor: isDisabled ? 'default' : 'pointer',
          opacity: isDisabled ? 0.55 : 1,
          transition: 'color 0.15s ease',
          ...theme.base,
          ...style,
        }}
      >
        {showIcon ? (copied ? <CheckGlyph size={sizing.icon} /> : <CopyGlyph size={sizing.icon} />) : null}
        {showLabel ? <span>{text}</span> : null}
        <span aria-live="polite" style={{ position: 'absolute', width: '1px', height: '1px', overflow: 'hidden', clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', whiteSpace: 'nowrap' }}>
          {copied ? copiedLabel : ''}
        </span>
      </button>
    );
  },
);

CopyButtonComponent.displayName = 'CopyButton';

export const CopyButton = CopyButtonComponent;
export const CopyToClipboard = CopyButtonComponent;
export const ClipboardButton = CopyButtonComponent;
export const CopyIconButton = CopyButtonComponent;

CopyButton.displayName = 'CopyButton';
CopyToClipboard.displayName = 'CopyToClipboard';
ClipboardButton.displayName = 'ClipboardButton';
CopyIconButton.displayName = 'CopyIconButton';

export default CopyButtonComponent;
"""


